import{_ as e,o as i,c as n,a4 as r}from"./chunks/framework.BBs01uty.js";const p=JSON.parse('{"title":"AI Agent 工程实践","description":"","frontmatter":{},"headers":[],"relativePath":"ai-agent/index.md","filePath":"ai-agent/index.md"}'),l={name:"ai-agent/index.md"};function t(o,a,h,s,g,c){return i(),n("div",null,[...a[0]||(a[0]=[r('<h1 id="ai-agent-工程实践" tabindex="-1">AI Agent 工程实践 <a class="header-anchor" href="#ai-agent-工程实践" aria-label="Permalink to &quot;AI Agent 工程实践&quot;">​</a></h1><div class="tip custom-block"><p class="custom-block-title">模块说明</p><p>本模块涵盖 AI 应用开发的完整知识体系：从 LLM API 调用、Agent 架构设计，到 Prompt Engineering、RAG 检索增强，再到 Spec-First 开发和 Harness 工程等进阶主题。</p></div><h2 id="🎯-学习目标" tabindex="-1">🎯 学习目标 <a class="header-anchor" href="#🎯-学习目标" aria-label="Permalink to &quot;🎯 学习目标&quot;">​</a></h2><p>通过本模块的学习，你将掌握：</p><ul><li><strong>基础概念</strong> - AI 开发常见名词和术语</li><li><strong>LLM API 开发</strong> - 调用 OpenAI/Claude API、流式响应、多轮对话</li><li><strong>Agent 架构设计</strong> - Function Calling、Chat/Agent/Workflow 三种模式</li><li><strong>Prompt Engineering</strong> - 基础技巧到高级思维链、ReAct 模式</li><li><strong>RAG 检索增强</strong> - 让 LLM 访问外部知识库</li><li><strong>工程化实践</strong> - 评估测试、可观测性、成本控制、安全防护</li><li><strong>Spec-First 开发</strong> - 规范优先的 AI 应用开发方法论</li><li><strong>AI Harness 工程</strong> - 构建可维护、可扩展的 AI 应用架构</li></ul><hr><h2 id="知识地图" tabindex="-1">知识地图 <a class="header-anchor" href="#知识地图" aria-label="Permalink to &quot;知识地图&quot;">​</a></h2><h3 id="_1-基础概念-⭐⭐⭐⭐⭐" tabindex="-1">1. 基础概念 ⭐⭐⭐⭐⭐ <a class="header-anchor" href="#_1-基础概念-⭐⭐⭐⭐⭐" aria-label="Permalink to &quot;1. 基础概念 ⭐⭐⭐⭐⭐&quot;">​</a></h3><p>AI 开发的核心术语和名词解释。</p><ul><li><a href="/knowledge/ai-agent/glossary.html">名词解释</a> - LLM、Token、RAG、Agent 等术语速查</li><li><a href="/knowledge/ai-agent/llm-landscape.html">大模型全景介绍</a> - 开源/闭源主流大模型：GPT、Claude、Qwen、DeepSeek 等</li></ul><h3 id="_2-ai-应用开发-⭐⭐⭐⭐⭐" tabindex="-1">2. AI 应用开发 ⭐⭐⭐⭐⭐ <a class="header-anchor" href="#_2-ai-应用开发-⭐⭐⭐⭐⭐" aria-label="Permalink to &quot;2. AI 应用开发 ⭐⭐⭐⭐⭐&quot;">​</a></h3><p>从零开始构建 AI 应用的核心知识。</p><ul><li><a href="/knowledge/ai-agent/llm-api-basics.html">LLM API 调用基础</a> - OpenAI/Claude API、流式响应、Token 计费、错误处理</li><li><a href="/knowledge/ai-agent/function-calling.html">Function Calling 与工具调用</a> - 让 LLM 调用外部工具执行任务</li><li><a href="/knowledge/ai-agent/app-architecture.html">AI 应用架构模式</a> - Chat/Agent/Workflow 三种模式、记忆管理、多 Agent 协作</li><li><a href="/knowledge/ai-agent/langchain-introduction.html">LangChain 框架介绍</a> - LLM 应用开发框架：组件、LCEL、LangGraph/LangSmith 生态</li><li><a href="/knowledge/ai-agent/app-engineering.html">AI 应用工程化实践</a> - 评估测试、可观测性、成本控制、安全防护</li></ul><h3 id="_3-prompt-engineering-⭐⭐⭐" tabindex="-1">3. Prompt Engineering ⭐⭐⭐ <a class="header-anchor" href="#_3-prompt-engineering-⭐⭐⭐" aria-label="Permalink to &quot;3. Prompt Engineering ⭐⭐⭐&quot;">​</a></h3><p>通过优化与 LLM 的交互方式获得更高质量的回答。</p><ul><li><a href="/knowledge/ai-agent/prompt-engineering/basics.html">基础技巧</a> - Role/Context/Task 结构、Few-shot、CoT</li><li><a href="/knowledge/ai-agent/prompt-engineering/advanced.html">高级技巧</a> - Self-Consistency、Tree of Thoughts、ReAct</li></ul><h3 id="_4-rag-检索增强-⭐⭐⭐⭐" tabindex="-1">4. RAG 检索增强 ⭐⭐⭐⭐ <a class="header-anchor" href="#_4-rag-检索增强-⭐⭐⭐⭐" aria-label="Permalink to &quot;4. RAG 检索增强 ⭐⭐⭐⭐&quot;">​</a></h3><p>让 LLM 能够访问和利用外部知识库。</p><ul><li><a href="/knowledge/ai-agent/rag/introduction.html">RAG 入门</a> - 向量检索、文档切片、检索增强生成流程</li></ul><h3 id="_5-spec-first-开发-⭐⭐⭐⭐⭐" tabindex="-1">5. Spec-First 开发 ⭐⭐⭐⭐⭐ <a class="header-anchor" href="#_5-spec-first-开发-⭐⭐⭐⭐⭐" aria-label="Permalink to &quot;5. Spec-First 开发 ⭐⭐⭐⭐⭐&quot;">​</a></h3><p>规范优先的开发模式，适合复杂的 AI Agent 项目。</p><ul><li><a href="/knowledge/ai-agent/spec-first/guide.html">Spec-First 指南</a> - Scripts prepare facts, LLM decides</li></ul><h3 id="_6-ai-harness-工程-⭐⭐⭐⭐⭐" tabindex="-1">6. AI Harness 工程 ⭐⭐⭐⭐⭐ <a class="header-anchor" href="#_6-ai-harness-工程-⭐⭐⭐⭐⭐" aria-label="Permalink to &quot;6. AI Harness 工程 ⭐⭐⭐⭐⭐&quot;">​</a></h3><p>构建企业级 AI 应用的工程化实践。</p><ul><li><a href="/knowledge/ai-agent/harness-engineering/core-concepts.html">核心思想</a> - Harness Engineering 三层模型</li><li><a href="/knowledge/ai-agent/harness-engineering/best-practices.html">最佳实践</a> - 项目结构、Prompt 管理、错误处理</li><li><a href="/knowledge/ai-agent/harness-engineering/quality-control.html">质量控制</a> - 评估与质量保障</li></ul><h3 id="_7-案例研究-⭐⭐⭐" tabindex="-1">7. 案例研究 ⭐⭐⭐ <a class="header-anchor" href="#_7-案例研究-⭐⭐⭐" aria-label="Permalink to &quot;7. 案例研究 ⭐⭐⭐&quot;">​</a></h3><p>工业级 AI 应用的实践案例。</p><ul><li><a href="/knowledge/ai-agent/case-studies/qoder.html">Qoder 优化实践</a> - AI IDE 的 Harness Engineering 实践</li></ul><hr><h2 id="💡-学习建议" tabindex="-1">💡 学习建议 <a class="header-anchor" href="#💡-学习建议" aria-label="Permalink to &quot;💡 学习建议&quot;">​</a></h2><h3 id="入门路径-开发-ai-应用" tabindex="-1">入门路径（开发 AI 应用） <a class="header-anchor" href="#入门路径-开发-ai-应用" aria-label="Permalink to &quot;入门路径（开发 AI 应用）&quot;">​</a></h3><ol><li><a href="/knowledge/ai-agent/glossary.html">名词解释</a> — 先搞懂术语</li><li><a href="/knowledge/ai-agent/llm-api-basics.html">LLM API 调用基础</a> — 学会调用模型</li><li><a href="/knowledge/ai-agent/function-calling.html">Function Calling</a> — 让模型使用工具</li><li><a href="/knowledge/ai-agent/app-architecture.html">AI 应用架构模式</a> — 理解三种架构</li><li>动手写一个带工具调用的 Chat 应用</li></ol><h3 id="进阶路径-工程化" tabindex="-1">进阶路径（工程化） <a class="header-anchor" href="#进阶路径-工程化" aria-label="Permalink to &quot;进阶路径（工程化）&quot;">​</a></h3><ol><li><a href="/knowledge/ai-agent/app-engineering.html">AI 应用工程化实践</a> — 评估、监控、成本、安全</li><li><a href="/knowledge/ai-agent/harness-engineering/core-concepts.html">Harness 核心思想</a> — 工程闭环</li><li><a href="/knowledge/ai-agent/spec-first/guide.html">Spec-First 指南</a> — 工作流治理</li></ol><h3 id="prompt-优化路径" tabindex="-1">Prompt 优化路径 <a class="header-anchor" href="#prompt-优化路径" aria-label="Permalink to &quot;Prompt 优化路径&quot;">​</a></h3><ol><li><a href="/knowledge/ai-agent/prompt-engineering/basics.html">Prompt 基础技巧</a></li><li><a href="/knowledge/ai-agent/prompt-engineering/advanced.html">Prompt 高级技巧</a></li><li><a href="/knowledge/ai-agent/rag/introduction.html">RAG 入门</a></li></ol><hr><h2 id="🔗-相关资源" tabindex="-1">🔗 相关资源 <a class="header-anchor" href="#🔗-相关资源" aria-label="Permalink to &quot;🔗 相关资源&quot;">​</a></h2><h3 id="官方文档" tabindex="-1">官方文档 <a class="header-anchor" href="#官方文档" aria-label="Permalink to &quot;官方文档&quot;">​</a></h3><ul><li><a href="https://platform.openai.com/docs" target="_blank" rel="noreferrer">OpenAI API Docs</a></li><li><a href="https://docs.anthropic.com/claude/docs" target="_blank" rel="noreferrer">Anthropic Claude API</a></li><li><a href="https://js.langchain.com/docs" target="_blank" rel="noreferrer">LangChain Documentation</a></li></ul><h3 id="开源项目" tabindex="-1">开源项目 <a class="header-anchor" href="#开源项目" aria-label="Permalink to &quot;开源项目&quot;">​</a></h3><ul><li><a href="https://github.com/langchain-ai/langchain" target="_blank" rel="noreferrer">LangChain</a> - AI 应用开发框架</li><li><a href="https://github.com/microsoft/autogen" target="_blank" rel="noreferrer">AutoGen</a> - Multi-Agent 框架</li><li><a href="https://github.com/run-llama/LlamaIndexTS" target="_blank" rel="noreferrer">LlamaIndex</a> - 数据索引与检索</li></ul><h3 id="学习资源" tabindex="-1">学习资源 <a class="header-anchor" href="#学习资源" aria-label="Permalink to &quot;学习资源&quot;">​</a></h3><ul><li><a href="https://www.promptingguide.ai/" target="_blank" rel="noreferrer">Prompt Engineering Guide</a> - Prompt 工程指南</li><li><a href="http://spec-first.cn" target="_blank" rel="noreferrer">Spec-First.cn</a> - Spec-First 开发社区</li></ul>',44)])])}const u=e(l,[["render",t]]);export{p as __pageData,u as default};
